export interface ResponseBody {
    status?: boolean;
    errorMessage?: string;
    errorMessages?: string[];
    [key: string]: any;
}

export interface ApiResponse {
    statusCode: number;
    headers: {
        "Access-Control-Allow-Origin": string;
        "Access-Control-Allow-Credentials": boolean;
        "Access-Control-Max-Age": number;
    };
    body: string;
}